System.register("chunks:///_virtual/manifest2.ts",["cc"],(function(e){var a;return{setters:[function(e){a=e.cclegacy}],execute:function(){a._RF.push({},"c4496XZ4aVJ26sKAo3UgxOu","manifest",void 0);e("MANIFEST",{manifest_version:1,game_id:"sg-sudoku",slug:"sudoku",name:{en:"Sudoku Pop"},description:{en:"Classic 9×9 sudoku with a fresh puzzle every game. Three levels, pencil notes, beat the clock."},genre:"puzzle",template_id:"sudoku",engine:"cocos-3.8.8",version:"1.0.0",orientation:"portrait",game_rules:{variant:"classic_sudoku",max_mistakes:3,modes:[{id:"easy",givens:40,technique:"naked_singles",base_points:3e3},{id:"medium",givens:32,technique:"singles",base_points:5e3},{id:"hard",givens:26,technique:"any",base_points:8e3}]},scoring_rules:{points:"solve_speed",per_second:2,mistake_penalty:300,floor_percent:20},supported_platforms:["web","telegram"],supported_locales:["en"],default_locale:"en",target_countries:["*"],age_rating:"PEGI 3",privacy_profile:{personal_data:!1,analytics:"pseudonymous_install",account_required:!1},monetization_profile:{rewarded_ads:!1,interstitial_ads:!1,iap:!0},social_profile:{share:!0,leaderboard:!0,challenge:!0},analytics_profile:{sink:"memory",flush_interval_ms:5e3},difficulty_config:{level:"normal"},asset_manifest:{theme:"settegames",palette:{background:"#FF8A3D",primary:"#3B82FF",accent:"#FFC83D",text:"#1A0B4B",muted:"#F4F6FF"},sounds:"synth",provenance:"Colori dal brand kit SetteGames (blu #3B82FF come campo, rosa, giallo, viola-scuro, bianco-lavanda); caratteri Titan One e Baloo 2 (OFL, da Scopa, come Perfect Timer); suoni sintetizzati dal codice; griglia, cifre e icone disegnate dal codice. Puzzle generati dal nostro codice (templates/sudoku/logic/generator.ts) a partire dal seme del server: nessun puzzle di terzi. Direzione: .impeccable.md"},build_config:{targets:["web-mobile"],max_gzip_kb:1200},release_config:{channels:["web","telegram"],status:"draft",telegram_bot:"SudokuClassicBot"},legal_status:{original_concept:!1,trademark_check:"pending",gambling_mechanics:!1,notes:'"Sudoku" è il nome generico del rompicapo numerico a griglia 9×9 (regole di pubblico dominio, derivate dal "Number Place" degli anni \'70). Il nome è usato solo come descrizione del genere. Nessun puzzle, codice, grafica, logo, font o testo di terzi: i puzzle sono generati dal nostro codice (generatore e risolutore scritti da zero in templates/sudoku/logic) dal seme del server, la grafica è disegnata dal codice con la palette del brand SetteGames. Nessun marchio di terzi nelle parole chiave SEO. Da confermare il controllo marchi prima della pubblicazione.'},experiment_config:{active:[]},seo:{keywords:["sudoku","play sudoku online","sudoku free online","daily sudoku","free sudoku","easy sudoku","hard sudoku","sudoku puzzle"],headline:{en:"Play Sudoku online"},long_description:{en:"Play sudoku online for free in your browser or on Telegram, with no download and no sign-up. Every game deals a fresh 9×9 puzzle with exactly one solution, in three levels: Easy, Medium and Hard. Use pencil notes to track candidates, watch rows, columns and boxes light up as you complete them, and race the clock for a higher score on the weekly leaderboard. A quick puzzle on the bus or a daily sudoku habit: it is ready when you are."},how_to_play:{en:["Fill the 9×9 grid so that every row, every column and every 3×3 box contains the numbers 1 to 9 exactly once.","Tap an empty cell, then tap a number on the pad (on a computer you can also type 1-9 and move with the arrow keys).","Turn on Notes to write small candidate numbers in a cell; tap a note again to remove it.","A wrong number turns red and counts as a mistake: erase it or write over it. Three mistakes end the game.","Solve the puzzle fast and cleanly: your score starts from the level's base points and drops with time and mistakes."]},faq:[{q:{en:"Is this sudoku free to play?"},a:{en:"Yes. Every level and every puzzle is free in your browser or on Telegram, with no download and no account. Optional color themes are cosmetic only and never change the puzzles or the scores."}},{q:{en:"Does every puzzle have a single solution?"},a:{en:"Yes. Puzzles are generated by our own code and each one is checked to have exactly one solution, so you can always solve it by logic, without guessing."}},{q:{en:"What is the difference between Easy, Medium and Hard?"},a:{en:"Easy starts with about 40 numbers and every next step is a cell with only one possible number. Medium starts with about 32 and sometimes asks you to find the only place for a number in a row, column or box. Hard starts with about 26 and needs deeper reasoning, so pencil notes really help."}},{q:{en:"Any sudoku tips for beginners?"},a:{en:"Start with the numbers that already appear most often and scan each 3×3 box for where they can still go. Look for cells where eight numbers are already ruled out by their row, column and box. When you get stuck, write the candidates as notes in a box or row and look for a number that fits in only one cell."}},{q:{en:"How is the score calculated?"},a:{en:"Only solved puzzles score. You start from the level's base points (3,000 Easy, 5,000 Medium, 8,000 Hard) and lose 2 points per second and 300 points per mistake, never dropping below 20% of the base. Scores are checked by replaying your moves on our server."}},{q:{en:"Can I play a daily sudoku?"},a:{en:"Yes. Every game deals a brand-new puzzle, so you can make it a daily habit at any level. Your best score for each level is saved, and the weekly leaderboard starts fresh every week."}}]}}),e("BUILD_INFO",{hash:"49dbcdb6bffbf50b",hubUrl:"https://jvmpwhoosojharlbmgsi.supabase.co/functions/v1/hub-api"});a._RF.pop()}}}));

